def load_directions_ny_chicago(**_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0031000" if __import__("os").path.isdir("./environment_mix/0031000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "load_directions_ny_chicago"

    if _extra:
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "This endpoint takes no parameters.", unexpected_params=sorted(list(_extra.keys())), latency_ms=latency_ms)

    data = _load("directions_ny_chicago.json")
    if isinstance(data, list):
        payload = data[0] if data else {"routes": [], "status": "ZERO_RESULTS"}
    elif isinstance(data, dict):
        payload = data
    else:
        payload = {"routes": [], "status": "ZERO_RESULTS"}

    return payload

